from sympy.parsing.sympy_parser import parse_expr, standard_transformations, convert_xor, implicit_multiplication_application
for s in ['7425000','1000','1000.99','1.22','0.4','2/3','x^2 + 3*x','1+1','123.45','12','1e5','.4']:
    try:
        print(repr(s),'->',repr(parse_expr(s, transformations=standard_transformations+(convert_xor,))))
    except Exception as e:
        print(repr(s),'-> ERR',type(e).__name__, e)
# check implicit transforms needed for '1/2 * (1/2)'
for s in ['(1/2) * (1/2) * P(A)', '2/3']:
    try:
        print(repr(s),'->',repr(parse_expr(s, transformations=standard_transformations+(convert_xor,))))
    except Exception as e:
        print(repr(s),'-> ERR',type(e).__name__, e)
EOF
